async function dumpTextFromPage(pageId) {
  const page = await figma.getNodeByIdAsync(pageId);
  if (!page) return `Page ${pageId} not found.`;

  const textNodes = [];
  function traverse(node) {
    if (node.type === "TEXT") {
      textNodes.push({
        name: node.name,
        characters: node.characters,
        x: node.absoluteTransform ? node.absoluteTransform[0][2] : 0,
        y: node.absoluteTransform ? node.absoluteTransform[1][2] : 0
      });
    }
    if ("children" in node) {
      for (const child of node.children) {
        traverse(child);
      }
    }
  }
  traverse(page);

  // Sort text nodes by y, then x to read top-to-bottom, left-to-right
  textNodes.sort((a, b) => {
    if (Math.abs(a.y - b.y) < 20) {
      return a.x - b.x;
    }
    return a.y - b.y;
  });

  return textNodes.map(t => `[${t.name}] ${t.characters}`).join("\n\n");
}

