(async () => {
  // Let's create the 11 frames on the canvas first and position them correctly.
  const page = await figma.getNodeByIdAsync("2002:2");
  if (!page) return "Page not found";

  const frameNames = [
    "01_Splash",
    "02_Home",
    "03_Product_Cheeseburger",
    "04_Product_Veggie",
    "05_Product_Chicken",
    "06_Product_Fried_Chicken",
    "07_Customize",
    "08_Payment",
    "09_Payment_Success_Overlay",
    "10_Profile",
    "11_Support_Chat"
  ];

  const frames = {};
  for (let i = 0; i < frameNames.length; i++) {
    const name = frameNames[i];
    let frame = page.children.find(c => c.name === name);
    if (!frame) {
      frame = figma.createFrame();
      frame.name = name;
      page.appendChild(frame);
    }
    frame.resize(430, 932);
    frame.x = i * 500;
    frame.y = 0;
    frame.backgrounds = [{ type: "SOLID", color: { r: 0.98, g: 0.98, b: 0.98 } }]; // F8F9FA
    frames[name] = frame.id;
  }

  return frames;
})()

(async () => {
  // Let's copy Status Bar and Home Indicator components to all 11 frames.
  // Note: 49:130 is Status Bar, 49:141 is Home Indicator.
  const page = await figma.getNodeByIdAsync("2002:2");
  if (!page) return "Page not found";

  const statusBarMaster = await figma.getNodeByIdAsync("49:130");
  const homeIndicatorMaster = await figma.getNodeByIdAsync("49:141");
  if (!statusBarMaster || !homeIndicatorMaster) return "Shell masters not found!";

  const frameIds = [
    "2004:2", "2004:3", "2004:4", "2004:5", "2004:6",
    "2004:7", "2004:8", "2004:9", "2004:10", "2004:11", "2004:12"
  ];

  for (const fid of frameIds) {
    const frame = await figma.getNodeByIdAsync(fid);
    if (!frame) continue;

    // Clear any existing instances of Status Bar or Home Indicator
    for (const child of [...frame.children]) {
      if (child.name === "Status Bar" || child.name === "Home Indicator" || child.name === "Shell") {
        child.remove();
      }
    }

    // Create Status Bar instance
    const sb = statusBarMaster.createInstance();
    sb.name = "Status Bar";
    sb.x = 0;
    sb.y = 0;
    frame.appendChild(sb);

    // Create Home Indicator instance
    const hi = homeIndicatorMaster.createInstance();
    hi.name = "Home Indicator";
    hi.x = 0;
    hi.y = frame.height - hi.height;
    frame.appendChild(hi);
  }

  return "Status Bar and Home Indicator instanced into all 11 frames.";
})()

