  const catWidths = [64, 88, 88, 88];
  let currentX = 24;

  for (let i = 0; i < categories.length; i++) {
    const cat = categories[i];
    const isCurrent = cat === "All";

    // Create button container
    const catBtn = figma.createFrame();
    catBtn.name = `Category_${cat}`;
    catBtn.resize(catWidths[i], 40);
    catBtn.x = currentX;
    catBtn.y = 256;
    catBtn.cornerRadius = 12;

    if (isCurrent) {
      // Primary red background for selected
      catBtn.backgrounds = [{ type: "SOLID", color: { r: 0.9372549, g: 0.1647059, b: 0.2235294 } }];
    } else {
      // White background with border
      catBtn.backgrounds = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
      catBtn.strokes = [{ type: "SOLID", color: { r: 0.9, g: 0.9, b: 0.9 } }];
      catBtn.strokeWeight = 1;
    }

    // Add text label
    const label = figma.createText();
    label.characters = cat;
    label.fontSize = 14;
    label.fontName = { family: "Roboto", style: isCurrent ? "Bold" : "Regular" };
    label.fills = [{ type: "SOLID", color: isCurrent ? { r: 1, g: 1, b: 1 } : { r: 0.4, g: 0.4, b: 0.4 } }];

    // Center alignment
    label.x = (catWidths[i] - label.width) / 2;
    label.y = (40 - label.height) / 2;
    catBtn.appendChild(label);

    homeFrame.appendChild(catBtn);
    currentX += catWidths[i] + 12;
  }

  return "Categories added to Home frame.";
})()

