  // Let's modify the Customize carousels generation to handle Check as a clone or createInstance depending on type.

  await figma.loadFontAsync({ family: "Roboto", style: "Regular" });
  await figma.loadFontAsync({ family: "Roboto", style: "Medium" });
  await figma.loadFontAsync({ family: "Roboto", style: "Bold" });

  const frame = await figma.getNodeByIdAsync("2004:8"); // 07_Customize
  if (!frame) return "Customize frame not found";

  // Clean up any Toppings, Side options, and Footers from previous run to avoid duplicates
  for (const child of [...frame.children]) {
    if (child.name.startsWith("Topping_") || child.name.startsWith("Side_") || child.name === "Footer" || child.name === "Toppings" || child.name === "Side options") {
      child.remove();
    }
  }

  const plusMaster = await figma.getNodeByIdAsync("1:387"); // COMPONENT
  const checkMaster = await figma.getNodeByIdAsync("1:401"); // FRAME (clone it)
  const orderNowBtnMaster = await figma.getNodeByIdAsync("1:473"); // COMPONENT

  // 1. Toppings Carousel
  const topTitle = figma.createText();
  topTitle.characters = "Toppings";
  topTitle.fontSize = 18;
  topTitle.fontName = { family: "Roboto", style: "Bold" };
  topTitle.fills = [{ type: "SOLID", color: { r: 0.235, g: 0.184, b: 0.184 } }];
  topTitle.x = 24;
  topTitle.y = 570;
  frame.appendChild(topTitle);

  const toppingsData = [
    { name: "Tomato", imageId: "1:252", added: true },
    { name: "Onions", imageId: "1:257", added: false },
    { name: "Pickles", imageId: "1:262", added: false },
    { name: "Bacon", imageId: "1:267", added: false },
    { name: "Cheese", imageId: "1:272", added: true },
    { name: "Mushroom", imageId: "1:277", added: false },
    { name: "Avocado", imageId: "1:282", added: false }
  ];

  let tx = 24;
  for (const top of toppingsData) {
    const card = figma.createFrame();
    card.name = `Topping_${top.name}`;
    card.resize(100, 130);
    card.x = tx;
    card.y = 604;
    card.cornerRadius = 16;
    card.backgrounds = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
    card.strokes = [{ type: "SOLID", color: top.added ? { r: 0.9372549, g: 0.1647059, b: 0.2235294 } : { r: 0.92, g: 0.92, b: 0.92 } }];
    card.strokeWeight = top.added ? 2 : 1;

    // Image
    const imgMaster = await figma.getNodeByIdAsync(top.imageId);
    if (imgMaster) {
      const img = imgMaster.clone();
      const ratio = img.height / img.width;
      const targetW = 60;
      const targetH = targetW * ratio;
      img.resize(targetW, targetH);
      img.x = (100 - targetW) / 2;
      img.y = 12;
      card.appendChild(img);
    }

    // Text label
    const lbl = figma.createText();
    lbl.characters = top.name;
    lbl.fontSize = 13;
    lbl.fontName = { family: "Roboto", style: "Bold" };
    lbl.fills = [{ type: "SOLID", color: { r: 0.235, g: 0.184, b: 0.184 } }];
    lbl.x = (100 - lbl.width) / 2;
    lbl.y = 80;
    card.appendChild(lbl);

    // Action indicator icon
    const indicator = figma.createFrame();
    indicator.resize(20, 20);
    indicator.cornerRadius = 10;
    indicator.x = (100 - 20) / 2;
    indicator.y = 102;

    if (top.added) {
      indicator.backgrounds = [{ type: "SOLID", color: { r: 0.9372549, g: 0.1647059, b: 0.2235294 } }];
      if (checkMaster) {
        const chk = checkMaster.clone();
        chk.resize(12, 12);
        chk.x = 4;
        chk.y = 4;
        chk.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
        indicator.appendChild(chk);
      }
    } else {
      indicator.backgrounds = [{ type: "SOLID", color: { r: 0.9, g: 0.9, b: 0.9 } }];
      if (plusMaster) {
        const pls = plusMaster.createInstance();
        pls.resize(12, 12);
        pls.x = 4;
        pls.y = 4;
        pls.fills = [{ type: "SOLID", color: { r: 0.4, g: 0.4, b: 0.4 } }];
        indicator.appendChild(pls);
      }
    }
    card.appendChild(indicator);
    frame.appendChild(card);
    tx += 112;
  }

  // 2. Side Options Carousel
  const sideTitle = figma.createText();
  sideTitle.characters = "Side options";
  sideTitle.fontSize = 18;
  sideTitle.fontName = { family: "Roboto", style: "Bold" };
  sideTitle.fills = [{ type: "SOLID", color: { r: 0.235, g: 0.184, b: 0.184 } }];
  sideTitle.x = 24;
  sideTitle.y = 760;
  frame.appendChild(sideTitle);

  const sidesData = [
    { name: "Fries", imageId: "1:290", added: true },
    { name: "Coleslaw", imageId: "1:295", added: false },
    { name: "Salad", imageId: "1:300", added: false },
    { name: "Onion Rings", imageId: "1:305", added: false },
    { name: "Mozzarella", imageId: "1:310", added: false }
  ];

  let sx = 24;
  for (const side of sidesData) {
    const card = figma.createFrame();
    card.name = `Side_${side.name}`;
    card.resize(100, 130);
    card.x = sx;
    card.y = 794;
    card.cornerRadius = 16;
    card.backgrounds = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
    card.strokes = [{ type: "SOLID", color: side.added ? { r: 0.9372549, g: 0.1647059, b: 0.2235294 } : { r: 0.92, g: 0.92, b: 0.92 } }];
    card.strokeWeight = side.added ? 2 : 1;

    // Image
    const imgMaster = await figma.getNodeByIdAsync(side.imageId);
    if (imgMaster) {
      const img = imgMaster.clone();
      const ratio = img.height / img.width;
      const targetW = 60;
      const targetH = targetW * ratio;
      img.resize(targetW, targetH);
      img.x = (100 - targetW) / 2;
      img.y = 12;
      card.appendChild(img);
    }

    // Text label
    const lbl = figma.createText();
    lbl.characters = side.name;
    lbl.fontSize = 13;
    lbl.fontName = { family: "Roboto", style: "Bold" };
    lbl.fills = [{ type: "SOLID", color: { r: 0.235, g: 0.184, b: 0.184 } }];
    lbl.x = (100 - lbl.width) / 2;
    lbl.y = 80;
    card.appendChild(lbl);

    // Action indicator icon
    const indicator = figma.createFrame();
    indicator.resize(20, 20);
    indicator.cornerRadius = 10;
    indicator.x = (100 - 20) / 2;
    indicator.y = 102;

    if (side.added) {
      indicator.backgrounds = [{ type: "SOLID", color: { r: 0.9372549, g: 0.1647059, b: 0.2235294 } }];
      if (checkMaster) {
        const chk = checkMaster.clone();
        chk.resize(12, 12);
        chk.x = 4;
        chk.y = 4;
        chk.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
        indicator.appendChild(chk);
      }
    } else {
      indicator.backgrounds = [{ type: "SOLID", color: { r: 0.9, g: 0.9, b: 0.9 } }];
      if (plusMaster) {
        const pls = plusMaster.createInstance();
        pls.resize(12, 12);
        pls.x = 4;
        pls.y = 4;
        pls.fills = [{ type: "SOLID", color: { r: 0.4, g: 0.4, b: 0.4 } }];
        indicator.appendChild(pls);
      }
    }
    card.appendChild(indicator);
    frame.appendChild(card);
    sx += 112;
  }

  // 3. Footer
  const footer = figma.createFrame();
  footer.name = "Footer";
  footer.resize(430, 110);
  footer.x = 0;
  footer.y = 1090;
  footer.backgrounds = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
  footer.strokes = [{ type: "SOLID", color: { r: 0.92, g: 0.92, b: 0.92 } }];
  footer.strokeWeight = 1;

  const priceTitle = figma.createText();
  priceTitle.characters = "Total Price";
  priceTitle.fontSize = 14;
  priceTitle.fontName = { family: "Roboto", style: "Medium" };
  priceTitle.fills = [{ type: "SOLID", color: { r: 0.5, g: 0.5, b: 0.5 } }];
  priceTitle.x = 24;
  priceTitle.y = 20;
  footer.appendChild(priceTitle);

  const priceVal = figma.createText();
  priceVal.characters = "$16.48";
  priceVal.fontSize = 28;
  priceVal.fontName = { family: "Roboto", style: "Bold" };
  priceVal.fills = [{ type: "SOLID", color: { r: 0.235, g: 0.184, b: 0.184 } }];
  priceVal.x = 24;
  priceVal.y = 40;
  footer.appendChild(priceVal);

  if (orderNowBtnMaster) {
    const orderBtn = orderNowBtnMaster.createInstance();
    orderBtn.resize(200, 56);
    orderBtn.x = frame.width - 24 - 200;
    orderBtn.y = 24;
    const labelTextNode = orderBtn.children.find(c => c.name === "Label");
    if (labelTextNode) {
      labelTextNode.characters = "Order Now";
    }
    footer.appendChild(orderBtn);
  }
  frame.appendChild(footer);

  return "Customize frame Toppings and Side Options recreated successfully using .clone() for FRAME nodes!";
})()

