(async () => {
  // Let's inspect reaction property structure in Figma plugin API.
  // The action type for navigation in Figma API is:
  // - trigger: { type: "ON_CLICK" } or { type: "AFTER_TIMEOUT", timeout: 1500 } (since AFTER_DELAY was renamed to AFTER_TIMEOUT, or maybe is just different)
  // - action: { type: "NODE", destinationId: targetId, navigation: "NAVIGATE", transition: { type: "DISSOLVE", duration: 0.3, easing: { type: "EASE_IN_AND_OUT" } } }
  // Wait, let's write a script that queries one existing prototype node if possible, or checks what types are allowed.
  // Let's test if we can check reactions schemas or just use a standard simple structure:
  // trigger: { type: "ON_CLICK" }
  // action: { type: "NODE", destinationId: target, navigation: "NAVIGATE", transition: null }
  // Wait, the error said:
  // - expected type to be "BACK" | "CLOSE" or similar, or "URL" or "CONDITIONAL" or "SET_VARIABLE"...
  // Ah! To navigate, is type "NODE"?
  // Yes! The error lists:
  // Unrecognized key(s) in object: 'destinationId', 'navigation', 'transition' at [0].actions[0]
  // Wait! Let's read the error details:
  // "Required value missing at [0].actions[0].transition.easing" -> Oh! transition needs "easing"!
  // And for trigger "AFTER_DELAY", it says:
  // "Invalid literal value, expected 'AFTER_TIMEOUT' at [0].trigger.type. Required value missing at [0].trigger.timeout."
  // Beautiful! This tells us:
  // 1. Use trigger `type: "AFTER_TIMEOUT", timeout: 1500` instead of `AFTER_DELAY`.
  // 2. Use `transition: { type: "DISSOLVE", duration: 0.3, easing: { type: "EASE_IN_AND_OUT" } }` (adding `easing`).
  // Let's run a test with just one connection to verify!

  const page = await figma.getNodeByIdAsync("2002:2");
  const f01 = page.children.find(c => c.name === "01_Splash");
  const f02 = page.children.find(c => c.name === "02_Home");

  if (!f01 || !f02) return "Frames not found";

  try {
    f01.reactions = [{
      trigger: { type: "AFTER_TIMEOUT", timeout: 1500 },
      actions: [{
        type: "NODE",
        destinationId: f02.id,
        navigation: "NAVIGATE",
        transition: { type: "DISSOLVE", duration: 0.3, easing: { type: "EASE_IN_AND_OUT" } }
      }]
    }];
    return "Test connection SUCCESS!";
  } catch (e) {
    return "Test connection FAILED: " + e.message;
  }
})()

